def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[r + dr][c + dc] == 3
                for dr in (-1, 0, 1)
                for dc in (-1, 0, 1)
                if dr or dc
            ):
                centers.append((r, c))

    rows = {r for r, c in centers}
    cols = {c for r, c in centers}

    # Extend each object's horizontal and vertical axes.
    for r in rows:
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = 1
    for c in cols:
        for r in range(h):
            if out[r][c] == 0:
                out[r][c] = 1

    # At crossings with a perpendicular 2-line, color the surrounding cells.
    for r in rows:
        for c in range(1, w - 1):
            if (grid[r][c] == 2 and r > 0 and r + 1 < h
                    and grid[r - 1][c] == 2 and grid[r + 1][c] == 2):
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = r + dr, c + dc
                        if (dr or dc) and grid[rr][cc] != 3:
                            out[rr][cc] = 1

    for c in cols:
        for r in range(1, h - 1):
            if (grid[r][c] == 2 and grid[r][c - 1] == 2
                    and grid[r][c + 1] == 2):
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = r + dr, c + dc
                        if (dr or dc) and grid[rr][cc] != 3:
                            out[rr][cc] = 1

    return out
